<script setup>
import { ref, reactive, computed, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import * as api from '@/api/writing-extensions'
const route=useRoute(), router=useRouter(), novel=computed(()=>Number(route.params.novelId))
const tab=ref('assets'), rows=ref([]), connections=ref([]), recaps=ref([]), events=ref([]), loading=ref(false), error=ref(''), jobs=ref([])
const sync=reactive({enabled:false,vectors:false,summaries:false,version:0})
const editor=ref(false), editId=ref(null), form=reactive({kind:'SAMPLE',name:'',body:'',state:'PENDING',metadata:{},expectedVersion:0})
const personalGlobal=ref(false),importGlobal=ref(false)
const kinds={SAMPLE:'样文',STYLE:'文风配置',SKILL:'个人 Skill'}, states={PENDING:'待确认',APPROVED:'已确认',INACTIVE:'停用'}
const styleChoices={sentenceLength:['SHORT','MIXED','LONG'],narrativeDistance:['CLOSE','NEUTRAL','DISTANT'],dialogueRatio:['LOW','MEDIUM','HIGH'],pacing:['SLOW','MEDIUM','FAST'],emotion:['SHOW','TELL','BALANCED'],imagery:['REALISTIC','LYRICAL','MINIMAL']}
const styleLabels={sentenceLength:'句长',narrativeDistance:'叙述距离',dialogueRatio:'对话比例',pacing:'节奏',emotion:'情绪表达',imagery:'意象'}
const valueLabels={SHORT:'短句',MIXED:'长短结合',LONG:'长句',CLOSE:'贴近人物',NEUTRAL:'中性',DISTANT:'疏离',LOW:'少',MEDIUM:'适中',HIGH:'多',SLOW:'舒缓',FAST:'紧凑',SHOW:'动作表现',TELL:'直接叙述',BALANCED:'结合',REALISTIC:'写实',LYRICAL:'抒情',MINIMAL:'简洁'}
async function action(fn){if(loading.value)return;loading.value=true;error.value='';try{await fn()}catch(e){if(e!=='cancel'&&e!=='close')error.value=e.message||'操作失败，请重试'}finally{loading.value=false}}
async function load(){const results=await Promise.allSettled([api.getAssets(novel.value),api.getMcp(novel.value),api.getSync(novel.value),api.getRecaps(novel.value),api.getSyncEvents(novel.value),api.getAnalyses(novel.value)]);const targets=[v=>rows.value=v,v=>connections.value=v,v=>Object.assign(sync,v),v=>recaps.value=v,v=>events.value=v,v=>jobs.value=v];results.forEach((r,i)=>{if(r.status==='fulfilled')targets[i](r.value);else error.value=r.reason?.message||'部分资料加载失败'});}
watch(novel,()=>action(load),{immediate:true})
function edit(row,kind='SAMPLE'){editId.value=row?.id||null;personalGlobal.value=!!row&&Number(row.novel_id)===0;Object.assign(form,{kind:row?.kind||kind,name:row?.name||'',body:row?.body||'',state:row?.state||'PENDING',metadata:structuredClone(api.parseJson(row?.metadata)),expectedVersion:Number(row?.version||0)});editor.value=true}
async function save(){await action(async()=>{await api.saveAsset(form.kind==='SKILL'&&personalGlobal.value?0:novel.value,editId.value,form);editor.value=false;await load();ElMessage.success('已保存')})}
async function erase(row){await action(async()=>{await ElMessageBox.confirm('永久删除此资料、历史正文及依赖的分析结果和会话；不修改小说正文。','删除资料',{type:'warning'});await api.deleteAsset(novel.value,row);await load()})}
async function analyze(row){await action(async()=>{await ElMessageBox.confirm('分析会将样文发送至配置的模型，可能产生费用。结果先保存为待确认文风，不导入样文剧情。','分析样文');jobs.value.unshift(await api.analyzeSample(novel.value,row.id));ElMessage.success('已排队，可刷新查看结果')})}
const importedFile=ref(null), imported=ref(null), importOpen=ref(false)
async function chooseFile(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;await action(async()=>{imported.value=await api.importSkill(novel.value,file,true);importedFile.value=file;importGlobal.value=false;importOpen.value=true})}
async function commitImport(){await action(async()=>{await api.importSkill(importGlobal.value?0:novel.value,importedFile.value);importOpen.value=false;await load()})}
const historyOpen=ref(false), history=ref([])
async function showHistory(row){await action(async()=>{history.value=await api.assetHistory(novel.value,row.id);historyOpen.value=true})}
async function saveSettings(){await action(async()=>{let acceptCost=false;if(sync.enabled&&(sync.vectors||sync.summaries)){await ElMessageBox.confirm('后续章节保存将自动调用向量／摘要 API，可能产生费用。已有章节需要另外点击“同步已有章节”。','自动同步费用');acceptCost=true}Object.assign(sync,await api.saveSync(novel.value,{...sync,expectedVersion:sync.version,acceptCost}));ElMessage.success('自动同步配置已保存')})}
async function backfill(){await action(async()=>{await ElMessageBox.confirm('按已保存的同步配置处理已有章节；开启向量或摘要时可能产生费用。','同步已有章节');await api.enqueueSync(novel.value);await load()})}
async function retry(row){await action(async()=>{await ElMessageBox.confirm('继续处理此事件；若涉及模型可能再次产生费用。已完成的摘要会复用。','继续同步');await api.retrySync(novel.value,row.id);await load()})}
const mcpOpen=ref(false), connectionId=ref(null), connection=reactive({name:'',endpoint:'',token:'',clearToken:false,expectedVersion:0}), grantOpen=ref(false), grantRow=ref(null), grants=ref([])
function editConnection(row){connectionId.value=row?.id||null;Object.assign(connection,{name:row?.name||'',endpoint:row?.endpoint||'',token:'',clearToken:false,expectedVersion:Number(row?.version||0)});mcpOpen.value=true}
async function persistConnection(){await action(async()=>{await api.saveMcp(novel.value,connectionId.value,connection);connection.token='';mcpOpen.value=false;await load()})}
async function discover(row){await action(async()=>{await api.discoverMcp(novel.value,row.id);await load()})}
function authorize(row){grantRow.value=row;grants.value=[...api.parseJson(row.grants)];grantOpen.value=true}
async function grant(){await action(async()=>{await api.grantMcp(novel.value,grantRow.value.id,{expectedVersion:grantRow.value.version,tools:grants.value,confirmReadOnly:true});grantOpen.value=false;await load()})}
</script>
<template>
  <main class="lab" v-loading="loading">
    <header><div><h2>写作资料与扩展</h2><p>样文、表达规则、外部参考与自动回顾由你选择；小说正文和设定仍由你掌握。</p></div><div><el-button @click="action(load)">刷新</el-button><el-button @click="router.push(`/novel/${novel}/work`)">返回写作</el-button></div></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <el-tabs v-model="tab">
      <el-tab-pane label="样文与个人 Skill" name="assets">
        <div class="actions"><el-button type="primary" @click="edit()">添加样文</el-button><el-button @click="edit(null,'SKILL')">新建 Skill</el-button><label class="file">导入 Skill.md / ZIP<input type="file" accept=".md,.zip" @change="chooseFile"></label></div>
        <p>样文只分析表达特征。文风配置需审核确认，才能在聊天框的“资料”中选择；个人 Skill 在底部 Skill 按钮选择。</p>
        <el-alert v-for="job in jobs" :key="job.id" :title="`样文分析：${job.state}${job.error ? ' · '+job.error : ''}`" :type="job.state==='FAILED'?'error':'info'" :closable="false" />
        <div class="cards"><article v-for="row in rows" :key="row.id"><h3>{{ row.name }} <el-tag size="small">{{ kinds[row.kind] }}</el-tag></h3><p>{{ states[row.state] }} · 版本 {{ row.version }}</p><pre>{{ row.body.slice(0,600) }}{{ row.body.length>600?'…':'' }}</pre><div class="actions"><el-button link @click="edit(row)">编辑 / 确认</el-button><el-button v-if="row.kind==='SAMPLE'" link type="primary" @click="analyze(row)">分析文风</el-button><el-button link @click="showHistory(row)">历史</el-button><el-button link type="danger" @click="erase(row)">删除</el-button></div></article></div>
        <el-empty v-if="!rows.length" description="还没有样文或个人规则" />
      </el-tab-pane>
      <el-tab-pane label="自动同步" name="sync"><div class="settings"><el-switch v-model="sync.enabled" active-text="章节保存后自动更新私有检索资料" /><el-checkbox v-model="sync.vectors">同时向量化（API 费用）</el-checkbox><el-checkbox v-model="sync.summaries">生成章节与累计回顾（API 费用）</el-checkbox><div><el-button type="primary" @click="saveSettings">保存配置</el-button><el-button :disabled="!sync.enabled" @click="backfill">同步已有章节</el-button></div></div><p>删除清理始终执行。模型失败不会自动反复计费，点击事件的“继续”后才会重试。</p><el-table :data="events"><el-table-column prop="chapter_id" label="章节" /><el-table-column prop="kind" label="变更" /><el-table-column prop="state" label="状态" /><el-table-column prop="error" label="说明" min-width="200" /><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.state==='NEEDS_RETRY'" link @click="retry(row)">继续</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="累计回顾" name="recap"><p>模型回顾用于导航，不是已核实事实；生成当前章只使用当前章之前的回顾，实际来源与版本可展开核对。</p><article v-for="row in recaps" :key="row.through_chapter_no"><h3>截至第 {{ row.through_chapter_no }} 章</h3><pre>{{ api.parseJson(row.summary).summary }}</pre><details><summary>来源和未确认事项</summary><pre>{{ api.parseJson(row.source_keys) }}</pre><pre>{{ api.parseJson(row.summary).unresolved }}</pre></details></article><el-empty v-if="!recaps.length" description="开启摘要并同步章节后，这里显示累计回顾" /></el-tab-pane>
      <el-tab-pane label="MCP 外部参考" name="mcp"><el-button type="primary" @click="editConnection()">添加连接</el-button><p>使用公共 HTTPS Streamable HTTP 端点。先获取工具目录，再明确授权只读工具；每个写作会话还需单独选择连接。外部参考不会自动成为小说事实。</p><article v-for="row in connections" :key="row.id"><h3>{{ row.name }} <el-tag>{{ row.enabled?'已授权':'未授权' }}</el-tag></h3><p>{{ row.endpoint }} · {{ row.tokenConfigured?'已保存令牌':'无令牌' }}</p><div class="actions"><el-button @click="editConnection(row)">修改</el-button><el-button @click="discover(row)">读取工具目录</el-button><el-button @click="authorize(row)">授权工具</el-button><el-button type="danger" @click="action(async()=>{await ElMessageBox.confirm('删除连接后现有任务不再调用此连接。','删除连接');await api.deleteMcp(novel,row.id);await load()})">删除</el-button></div></article></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="editor" :title="`${editId?'编辑':'新增'}${kinds[form.kind]}`" width="min(800px,95vw)"><el-checkbox v-if="form.kind==='SKILL'" v-model="personalGlobal" :disabled="!!editId">所有我的作品可用</el-checkbox><el-input v-model="form.name" placeholder="名称" maxlength="100" /><el-select v-model="form.state"><el-option v-for="(name,id) in states" :key="id" :label="name" :value="id" /></el-select><template v-if="form.kind==='STYLE'"><div v-for="(options,key) in styleChoices" :key="key" class="preference"><span>{{ styleLabels[key] }}</span><el-select v-model="form.metadata.preferences[key]"><el-option v-for="value in options" :key="value" :value="value" :label="valueLabels[value]" /></el-select></div><details><summary>样文分析依据</summary><pre>{{ form.metadata.observations }}</pre><p>读取 {{ form.metadata.readChars }} / {{ form.metadata.totalChars }} 字</p></details></template><el-input v-else v-model="form.body" type="textarea" :rows="15" :maxlength="form.kind==='SAMPLE'?60000:6000" show-word-limit :placeholder="form.kind==='SAMPLE'?'粘贴你有权使用的样文':'填写表达、格式、类型等规则。不能授予额外工具或数据权限。'" /><template #footer><el-button @click="editor=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
    <el-dialog v-model="importOpen" title="导入预览" width="min(700px,95vw)"><template v-if="imported"><h3>{{ imported.skill.name }}</h3><p>{{ imported.skill.description }}</p><pre>{{ imported.skill.instructions }}</pre><el-checkbox v-model="importGlobal">所有我的作品可用</el-checkbox><p>只导入文本和包内参考，不执行脚本。保存后仍需在编辑中确认。</p></template><template #footer><el-button @click="importOpen=false">取消</el-button><el-button type="primary" @click="commitImport">保存待确认 Skill</el-button></template></el-dialog>
    <el-dialog v-model="historyOpen" title="资料历史" width="min(800px,95vw)"><details v-for="row in history" :key="row.version"><summary>版本 {{ row.version }}</summary><pre>{{ api.parseJson(row.payload).body }}</pre></details></el-dialog>
    <el-dialog v-model="mcpOpen" title="MCP 连接" width="min(600px,95vw)"><el-input v-model="connection.name" placeholder="名称" /><el-input v-model="connection.endpoint" placeholder="https://example.com/mcp" /><el-input v-model="connection.token" type="password" show-password placeholder="Bearer Token，留空保留原令牌" autocomplete="off" /><el-checkbox v-model="connection.clearToken">清空令牌</el-checkbox><p>保存修改会撤销旧工具授权，需重新读取目录和授权。</p><template #footer><el-button @click="mcpOpen=false">取消</el-button><el-button type="primary" @click="persistConnection">保存</el-button></template></el-dialog>
    <el-dialog v-model="grantOpen" title="授予只读参考工具" width="min(650px,95vw)"><template v-if="grantRow"><p>远端的只读声明不能保证其实现安全，请仅接入你信任的服务。</p><el-checkbox-group v-model="grants"><div v-for="tool in api.parseJson(grantRow.catalog)" :key="tool.name"><el-checkbox :value="tool.name" :disabled="!tool.annotations?.readOnlyHint">{{ tool.name }}</el-checkbox><p>{{ tool.description }}</p></div></el-checkbox-group></template><template #footer><el-button @click="grantOpen=false">取消</el-button><el-button type="primary" @click="grant">确认只读授权</el-button></template></el-dialog>
  </main>
</template>
<style scoped>
.lab{padding:24px;max-width:1300px;margin:auto}header{display:flex;justify-content:space-between;gap:20px}h2{margin-top:0}p{line-height:1.7;color:#606266}.actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.actions :deep(.el-button){margin:0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px}article{background:white;border:1px solid #e4e7ed;border-radius:8px;padding:18px;margin:16px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7;font-family:inherit}.file{color:#409eff;cursor:pointer}.file input{display:none}.settings{display:flex;flex-direction:column;align-items:flex-start;gap:18px;padding:20px 0}.preference{display:flex;align-items:center;gap:20px;margin:12px 0}.preference span{width:80px}:deep(.el-dialog .el-input),:deep(.el-dialog .el-select){margin-bottom:12px}
</style>
